60	func declineReasonOf(t *testing.T, f scan.Finding) string {
61		t.Helper()
62		rule, ok := remediation.FixFor(f)
63		if !ok || rule.Declines == nil || rule.Declines(f) == "" {
64			t.Fatalf("%s must decline from the finding alone", f.ID)
65		}
66		return rule.Declines(f)
