259	// Pressing a greyed key says why, at the Warn level, and does nothing else: no
260	// modal, no viewer, no clipboard, and the detail stays where it is.
261	func TestAGreyedDetailKeyGivesItsReasonAndDoesNothing(t *testing.T) {
262		testutil.FastTimers(t, &components.FooterMsgDuration)
263		written := stubClipboard(t, nil)
264		for _, c := range actionCases(t) {
265			for key, reason := range c.reasons() {
266				if reason == "" {
267					continue
268				}
269				t.Run(c.name+"/"+key, func(t *testing.T) {
270					m := c.open(t)
271					before := *m.selectedFinding
272					m, cmd := step(t, m, testutil.Key(key))
273	
274					if m.footer.Text() != reason || m.footer.Level() != components.LevelWarning {
275						t.Errorf("footer = %q (level %v), want %q as a warning", m.footer.Text(), m.footer.Level(), reason)
276					}
277					if m.confirmModal != nil || m.misconfigPending != nil || m.findingToIgnore != nil {
278						t.Error("a refused key opened a confirmation")
279					}
280					if m.state != StateDetails || m.selectedFinding == nil || m.selectedFinding.ID != before.ID {
281						t.Error("a refused key left the detail")
282					}
283					for _, msg := range testutil.Msgs(cmd) {
284						switch msg.(type) {
285						case uiviewer.OpenRequestMsg, FixCommandCopiedMsg:
286							t.Errorf("a refused key emitted %T", msg)
287						}
288					}
289				})
290			}
291		}
292		if len(*written) != 0 {
293			t.Errorf("a refused key wrote %q to the clipboard", *written)
294		}
295	}
