19	// DEVDESK-751 (steps 4 and 7): the finding detail acts. Six keys, each greyed
20	// with its reason when it has nothing to act on (Rule 130), and each one
21	// acting on the finding on screen rather than on the table row behind it.
22	
23	// The six keys of the detail, in the order of the header column, and the words
24	// beside them. The descriptions are at most ten cells: the shortcut column is
25	// 19 cells wide at 80 columns and `<ctrl+o>` takes nine of them.
26	var detailKeys = []string{"esc", keymap.Web, "enter", "ctrl+o", keymap.Copy, keymap.Exclude}
27	
28	var detailDescriptions = map[string]string{
29		"esc":          "Back",
30		keymap.Web:     "Open ref",
31		"enter":        "Open file",
32		"ctrl+o":       "Apply fix",
33		keymap.Copy:    "Copy cmd",
34		keymap.Exclude: "Exclude",
35	}
