37	// gitleaksSecret is a Gitleaks finding with a fingerprint, the only kind X can
38	// put in .gitleaksignore.
39	func gitleaksSecret(file string, line int) scan.Finding {
40		return scan.Finding{
41			ID: "aws-access-token", Title: "AWS key committed", Severity: scan.SeverityHigh,
42			Source: scan.SourceGitleaks, File: file, Line: line, Match: "AKIA0000",
43			Fingerprint: file + ":aws-access-token:" + string(rune('0'+line%10)),
44			References:  []string{"https://example.test/aws"},
45		}
46	}
47	
48	// actionCase is one finding of the matrix of the detail's keys, with the reason
49	// each key is greyed for ("" = the key acts).
50	type actionCase struct {
51		name    string
52		f       scan.Finding
53		image   bool
54		enter   string
55		fix     string
56		copy    string
57		exclude string
58	}
59	
60	func declineReasonOf(t *testing.T, f scan.Finding) string {
61		t.Helper()
62		rule, ok := remediation.FixFor(f)
63		if !ok || rule.Declines == nil || rule.Declines(f) == "" {
64			t.Fatalf("%s must decline from the finding alone", f.ID)
65		}
66		return rule.Declines(f)
67	}
68	
69	func actionCases(t *testing.T) []actionCase {
70		t.Helper()
71		trivySecret := scan.Finding{ID: "aws-access-key-id", Title: "AWS key", Severity: scan.SeverityHigh,
72			Source: scan.SourceTrivySecret, File: "app/.env", Line: 3}
73		license := scan.Finding{ID: "GPL-3.0", Title: "Copyleft licence", Severity: scan.SeverityLow,
74			Source: scan.SourceTrivyLicense, File: "go.mod"}
75		ci := scan.Finding{ID: "pipeline-score", Title: "Pipeline", Severity: scan.SeverityMedium,
76			Source: scan.SourcePlumber, File: ".gitlab-ci.yml", Job: "build"}
77		instruction := cveWith("", "Update golang.org/x/net to 0.7.0")
78		if !scan.IsFixInstruction(instruction) {
79			t.Fatal("the fixture must be an instruction, not a command")
80		}
81		return []actionCase{
82			{name: "a CVE with a command", f: cveWith("gomod", "go get golang.org/x/net@v0.7.0"),
83				enter: reasonNoFile, fix: reasonNotMisconfigTab, copy: "", exclude: reasonNotASecret},
84			{name: "a CVE with an instruction", f: instruction,
85				enter: reasonNoFile, fix: reasonNotMisconfigTab, copy: reasonNoCommand, exclude: reasonNotASecret},
86			{name: "a Gitleaks secret", f: gitleaksSecret("config/prod.env", 12),
87				enter: "", fix: reasonNotMisconfigTab, copy: reasonNoCommand, exclude: ""},
88			{name: "a Trivy secret", f: trivySecret,
89				enter: "", fix: reasonNotMisconfigTab, copy: reasonNoCommand, exclude: reasonNotGitleaks},
90			{name: "a secret whose file leaves the target", f: gitleaksSecret("../etc/passwd", 1),
91				enter: reasonFileOutsideTarget, fix: reasonNotMisconfigTab, copy: reasonNoCommand, exclude: ""},
92			{name: "a license", f: license,
93				enter: "", fix: reasonNotMisconfigTab, copy: reasonNoCommand, exclude: reasonNotASecret},
94			{name: "a CI finding", f: ci,
95				enter: "", fix: reasonNotMisconfigTab, copy: reasonNoCommand, exclude: reasonNotASecret},
96			{name: "a built-in fix on a directory", f: misconfigOf("DS002"),
97				enter: "", fix: "", copy: reasonNoCommand, exclude: reasonNotASecret},
98			{name: "a built-in fix on an image", f: misconfigOf("DS002"), image: true,
99				enter: reasonFileNotOnDisk, fix: reasonFileNotOnDisk, copy: reasonNoCommand, exclude: reasonNotASecret},
100			{name: "a fix the finding declines", f: unconfinedSeccomp(),
101				enter: "", fix: declineReasonOf(t, unconfinedSeccomp()), copy: reasonNoCommand, exclude: reasonNotASecret},
102			{name: "a rule the catalog has no fix for", f: misconfigOf("KSV-0012"),
103				enter: "", fix: noFixReason(misconfigOf("KSV-0012")), copy: reasonNoCommand, exclude: reasonNotASecret},
104			{name: "a minimal finding", f: scan.Finding{ID: "X-1", Title: "Only a title"},
105				enter: reasonNoFile, fix: reasonNotMisconfigTab, copy: reasonNoCommand, exclude: reasonNotASecret},
106		}
107	}
