22	// fixDetail is the detail of a DS002 finding about a real Dockerfile.
23	func fixDetail(t *testing.T) (Model, string) {
24		t.Helper()
25		m, dir := misconfigModel(t, fixableDockerfile, "AVD-DS-0002")
26		m = feed(t, m, testutil.Key("enter"))
