45	// preparedFrom presses ctrl+o and runs the preparation, as the user and the
46	// runtime would.
47	func preparedFrom(t *testing.T, m Model) Model {
48		t.Helper()
49		m, cmd := step(t, m, testutil.Key(writeRemediationKey))
50		return feed(t, m, run(t, cmd))
51	}
