63			t.Fatalf("no confirmation (results %v, detail %v)", fromResults.confirmModal != nil, fromDetail.confirmModal != nil)
64		}
65		if got, want := fromDetail.confirmModal.View(), fromResults.confirmModal.View(); got != want {
66			t.Errorf("the confirmations differ:\nresults:\n%s\ndetail:\n%s", want, got)
67		}
