26	// stubClipboard takes the clipboard write for the test, and reports what was
27	// written. err is what the write answers.
28	func stubClipboard(t *testing.T, err error) *[]string {
29		t.Helper()
30		orig := writeClipboard
31		written := new([]string)
32		writeClipboard = func(text string) error {
33			*written = append(*written, text)
34			return err
35		}
36		t.Cleanup(func() { writeClipboard = orig })
37		return written
38	}
