121		}{
122			{"a plain command", "go get golang.org/x/net@v0.7.0", "go get golang.org/x/net@v0.7.0"},
123			{"a command with spaces and a newline around it", "  go get golang.org/x/net@v0.7.0 \n", "go get golang.org/x/net@v0.7.0"},
124			{"a command wider than any screen", long, long},
125		}
126		for _, tc := range tests {
