133				}
134	
135				m, cmd := step(t, m, testutil.Key(keymap.Copy))
136				if len(*written) != 0 {
137					t.Fatalf("Update wrote %q to the clipboard: the write belongs in the Cmd (Rule 110)", *written)
138				}
