150				m = feed(t, m, msg)
151				if m.footer.Text() != "Command copied to the clipboard" || m.footer.Level() != components.LevelInfo {
152					t.Errorf("footer = %q (level %v), want the Info confirmation", m.footer.Text(), m.footer.Level())
